#!/usr/bin/env bash
# TokenGuard Product v2: LIVE inference + replay + how-it-works + results.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
mkdir -p demo/static
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing TokenGuard v2 (live product)..."
decode "demo/server.py" << 'B64EOF'

B64EOF
decode "demo/static/index.html" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Two ways to run:"
echo "  SIMULATED (anywhere, no GPU):  TG_FAKE=1 python demo/server.py"
echo "  REAL LIVE (GPU session):       python demo/server.py --model Qwen/Qwen3-4B"
echo "Then: PORTS tab -> 8000 -> Open in Browser"